$root=sys_get_temp_dir().DIRECTORY_SEPARATOR.'kalite-filo-publish-'.bin2hex(random_bytes(5));function kalite_filo_admin_config():array{global $root;return['data_root'=>$root];}function kalite_filo_admin_ensure_private_directory(string $path):void{if(!is_dir($path)&&!mkdir($path,0700,true)&&!is_dir($path))throw new RuntimeException('directory');}function kalite_filo_admin_vehicle_store_path():string{global $root;return $root.DIRECTORY_SEPARATOR.'drafts'.DIRECTORY_SEPARATOR.'vehicles.json';}function kalite_filo_admin_article_store_path():string{global $root;return $root.DIRECTORY_SEPARATOR.'drafts'.DIRECTORY_SEPARATOR.'articles.json';}function kalite_filo_admin_media_catalog_path():string{global $root;return $root.DIRECTORY_SEPARATOR.'media'.DIRECTORY_SEPARATOR.'library'.DIRECTORY_SEPARATOR.'library.json';}function kalite_filo_admin_assert_vehicle_uniqueness(array $records):void{$seen=[];foreach($records as $record){$key=($record['id']??'').'|'.($record['sourceId']??'').'|'.($record['slug']??'');if(isset($seen[$key]))throw new InvalidArgumentException();$seen[$key]=true;}}function kalite_filo_admin_vehicle_records():array{$records=[];foreach(range(1,4)as$i)$records[]=['id'=>'vehicle-'.$i,'sourceId'=>'SOURCE-'.$i,'slug'=>'vehicle-'.$i,'featured'=>true,'publicationStatus'=>'published','priceAmountMinor'=>10000,'coverImage'=>['src'=>'/vehicle.jpg']];return$records;}function kalite_filo_admin_article_drafts():array{return[['id'=>'article-one','coverMediaId'=>null,'locales'=>['tr'=>['status'=>'ready']]]];}function kalite_filo_admin_media_records():array{return[['id'=>str_repeat('a',32),'checksum'=>str_repeat('b',64)]];}function kalite_filo_admin_taxonomy():array{return['make'=>[['value'=>'Renault']]];}function publish_assert(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);}function publish_remove(string $path):void{if(!is_dir($path))return;foreach(scandir($path)?:[]as$entry){if($entry==='.'||$entry==='..')continue;$item=$path.DIRECTORY_SEPARATOR.$entry;is_dir($item)?publish_remove($item):@unlink($item);}@rmdir($path);}require_once dirname(__DIR__).'/publishing-store.php';
try{mkdir(dirname(kalite_filo_admin_vehicle_store_path()),0700,true);file_put_contents(kalite_filo_admin_vehicle_store_path(),'{}');file_put_contents(kalite_filo_admin_article_store_path(),'{}');$_SESSION['identity']=['id'=>'owner'];$changes=kalite_filo_admin_unpublished_changes();publish_assert(count($changes)===2&&strlen($changes[0]['fingerprint'])===64,'Changes must use content fingerprints.');$request=kalite_filo_admin_create_staging_publish_request();publish_assert($request['status']==='awaiting_runner'&&$request['target']==='staging'&&strlen($request['snapshotHash'])===64,'Staging request must freeze a runner-pending snapshot.');$duplicate=kalite_filo_admin_create_staging_publish_request();publish_assert($duplicate['id']===$request['id'],'The same pending snapshot must be idempotent.');$safe=kalite_filo_admin_safe_publish_request($request);publish_assert(!array_key_exists('snapshot',$safe)&&!array_key_exists('fingerprint',$safe['changes'][0])&&$safe['changeCount']===2,'Browser history must not expose private snapshot fingerprints.');publish_assert(count(kalite_filo_admin_publish_requests())===1,'Private request history must round-trip.');$invalid=kalite_filo_admin_staging_publish_payload();$invalid['featuredVehicleIds']=['vehicle-1'];publish_assert(kalite_filo_admin_validate_staging_publish_payload($invalid)['valid']===false,'Featured invariant must block publish.');}finally{publish_remove($root);}fwrite(STDOUT,"Admin publishing store tests passed.\n");
